"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def maxSubarraySum(arr):
    maxSum = arr[0]
    currentSum = arr[0]
    for i in range(1, len(arr)):
        currentSum = max(arr[i], (currentSum + arr[i]))
        maxSum = max(maxSum, currentSum)
    return maxSum
print(maxSubarraySum([-3, -7, -2, -9]))
